internal sealed class WebsiteFixture:HttpMessageHandler
{
 internal const string Secret="k8v_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 internal string Scope="write";internal readonly List<(string Query,string Body)> Requests=[];internal readonly Dictionary<long,JsonObject> Records=[];internal readonly Queue<JsonObject> Pages=[];internal readonly HashSet<string> Deleted=[];internal Func<JsonArray,bool,JsonArray>? PushOverride;internal HttpStatusCode? Failure;internal bool Redirect,LeakSecret;private long next=100,cursor=10;
 internal static JsonObject Record(long id,string type,string reference="")=>new(){["id"]=id,["ref"]=reference,["rev"]=1,["type"]=type,["protocol"]="P25",["label"]="Synthetic "+type,["ids"]=new JsonObject(),["attrs"]=new JsonObject(),["parent"]=null,["target"]=null};
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken cancellationToken)
 {
  if(request.RequestUri!.Host!="mrs-fixture.invalid"||!request.Headers.TryGetValues("X-KE8-Token",out var tokens)||tokens.Single()!=Secret)throw new IOException("Fixture expected a header-only synthetic credential");string query=request.RequestUri.Query;string body=request.Content==null?"":await request.Content.ReadAsStringAsync(cancellationToken);Requests.Add((query,body));
  if(Redirect){var response=new HttpResponseMessage(HttpStatusCode.Redirect);response.Headers.Location=new("https://other-fixture.invalid/");return response;}
  if(Failure is {} code){var failed=Reply(new(){["api"]=1,["error"]="synthetic failure"},code);if(code==HttpStatusCode.TooManyRequests)failed.Headers.TryAddWithoutValidation("Retry-After","5");return failed;}
  if(query=="?r=me")return Reply(new(){["api"]=1,["user"]=new JsonObject{["id"]=7,["name"]="Fixture owner"},["scope"]=Scope});
  if(query.StartsWith("?r=changes")){if(!query.Contains("echo=1"))throw new IOException("Fixture requires echoed pulls");return Reply(Pages.Count>0?Pages.Dequeue():new(){["api"]=1,["cursor"]=cursor,["more"]=false,["changes"]=new JsonArray(Records.Values.Select(r=>(JsonNode)new JsonObject{["op"]="upsert",["record"]=r.DeepClone()}).ToArray())});}
  var items=JsonNode.Parse(body)!["items"]!.AsArray();bool dry=query.Contains("dry=1");if(PushOverride!=null)return Reply(new(){["api"]=1,["results"]=PushOverride(items,dry)});
  var results=new JsonArray();foreach(var value in items){var item=value!.AsObject();if(item.ContainsKey("force")||item.ContainsKey("revive"))throw new IOException("Fixture rejects force/revive");var record=item["record"]!.AsObject();string reference=SyncJson.Text(item["ref"]);long id=SyncJson.Number(item["id"]);var existing=id>0?Records.GetValueOrDefault(id):Records.Values.FirstOrDefault(r=>SyncJson.Text(r["ref"])==reference);
   if(Deleted.Contains(reference)||id>0&&existing==null){results.Add(new JsonObject{["status"]="gone",["ref"]=reference});continue;}
   if(existing!=null&&SyncJson.Number(item["base_rev"])!=SyncJson.Number(existing["rev"])){results.Add(new JsonObject{["status"]="conflict",["id"]=SyncJson.Number(existing["id"]),["server"]=existing.DeepClone()});continue;}
   string? missing=null;foreach(string field in new[]{"parent_ref","target_ref"}){string parent=SyncJson.Text(record[field]);if(parent.Length>0&&!Records.Values.Any(r=>SyncJson.Text(r["ref"])==parent))missing=field+" \""+parent+"\" was not found. Push the record it refers to first.";}
   if(missing!=null){results.Add(new JsonObject{["status"]="error",["errors"]=new JsonArray(missing)});continue;}
   long recordId=existing==null?++next:SyncJson.Number(existing["id"]);long revision=existing==null?1:SyncJson.Number(existing["rev"])+1;var merged=existing==null?Record(recordId,SyncJson.Text(record["type"]),reference):SyncJson.Copy(existing);foreach(var pair in record)merged[pair.Key]=pair.Value?.DeepClone();merged["id"]=recordId;merged["rev"]=revision;
   foreach(string field in new[]{"parent","target"}){string parent=SyncJson.Text(merged[field+"_ref"]);if(parent.Length>0)merged[field]=SyncJson.Number(Records.Values.Single(r=>SyncJson.Text(r["ref"])==parent)["id"]);}
   if(!dry){Records[recordId]=merged;cursor++;}results.Add(new JsonObject{["status"]=existing==null?"created":"updated",["ref"]=reference,["id"]=dry?null:JsonValue.Create(recordId),["rev"]=revision,["dry"]=dry});
  }return Reply(new(){["api"]=1,["results"]=results});
 }
 private HttpResponseMessage Reply(JsonObject body,HttpStatusCode code=HttpStatusCode.OK){if(LeakSecret)body["debug"]=Secret;return new(code){Content=new StringContent(body.ToJsonString(),Encoding.UTF8,"application/json")};}
 internal static JsonObject Page(long cursor,bool more,params JsonObject[] changes)=>new(){["api"]=1,["cursor"]=cursor,["more"]=more,["changes"]=new JsonArray(changes.Select(c=>(JsonNode)c).ToArray())};
 internal static JsonObject Up(JsonObject record)=>new(){["op"]="upsert",["record"]=record.DeepClone()};
}
